// Builds the collapsible "Field index" on every table page in wiki/tables/: every heading on the page,
// in order, grouped by section, each one a link to its documentation. The index goes right under the
// page's Contents list, between two marker comments, and is rewritten in place.
//   node wiki-field-index.js           update the pages
//   node wiki-field-index.js --check   exit 1 if any page's index is out of date (CI)
const fs = require('fs');
const path = require('path');

const tables = path.join(__dirname, '..', '..', 'wiki', 'tables');
const check = process.argv.includes('--check');
const START = '<!-- field-index:start (generated by .github/scripts/wiki-field-index.js; do not edit by hand) -->';
const END = '<!-- field-index:end -->';

// heading text as GitHub renders it: link syntax and inline code markers dropped
const plain = h => h.replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]*)\]\([^)]*\)/g, '$1').replace(/`/g, '').trim();
// GitHub's anchor for a heading
const slug = h => plain(h).toLowerCase().replace(/[^a-z0-9 _-]/g, '').replace(/ /g, '-');

function headings(lines) {
	const out = [];
	const counts = {};
	let fence = false;
	for (const line of lines) {
		if (/^```/.test(line)) fence = !fence;
		const m = !fence && line.match(/^(#{2,6}) (.+?)\s*$/);
		if (!m) continue;
		const s = slug(m[2]);
		counts[s] = (counts[s] || 0) + 1;
		out.push({ level: m[1].length, text: plain(m[2]), anchor: counts[s] > 1 ? `${s}-${counts[s] - 1}` : s });
	}
	return out;
}

const link = h => `[${h.text.replace(/([[\]|])/g, '\\$1')}](#${h.anchor})`;

function build(lines) {
	const all = headings(lines).filter(h => h.text !== 'Contents');
	const groups = [];
	for (const h of all) {
		if (h.level === 2) groups.push({ head: h, items: [] });
		else if (groups.length) groups[groups.length - 1].items.push(h);
	}
	const body = [];
	for (const g of groups) {
		if (!g.items.length) continue;
		// one field per line, in table order; sub-fields nested under their field
		const top = Math.min(...g.items.map(h => h.level));
		let prev = -1;
		const list = g.items.map(h => {
			const depth = Math.min(h.level - top, prev + 1);	// a list can only nest one level at a time
			prev = depth;
			return `${'  '.repeat(depth)}- ${link(h)}`;
		});
		body.push(`**${link(g.head)}**`, '', ...list, '');
	}
	if (!body.length) return null;
	return [START, '<details>', '<summary><b>Field index</b> (every field, one per line in table order; click one to jump to it)</summary>', '', ...body, '</details>', END];
}

let stale = 0;
for (const name of fs.readdirSync(tables).filter(f => f.endsWith('.md')).sort()) {
	const file = path.join(tables, name);
	const text = fs.readFileSync(file, 'utf8');
	const nl = text.includes('\r\n') ? '\r\n' : '\n';
	let lines = text.split(/\r?\n/);

	// drop an existing index
	const s = lines.indexOf(START);
	if (s >= 0) {
		const e = lines.indexOf(END, s);
		if (e < 0) throw new Error(`${name}: index start marker without end marker`);
		lines.splice(s, e - s + 1 + (lines[e + 1] === '' ? 1 : 0));
	}

	const index = build(lines);
	if (index) {
		const c = lines.indexOf('## Contents');
		if (c < 0) throw new Error(`${name}: no "## Contents" to put the field index under`);
		let i = c + 1;
		while (i < lines.length && (lines[i] === '' || /^\s*(\d+\.|-)\s/.test(lines[i]))) i++;
		// i is the first line after the Contents list and its blank lines; put the index before it
		lines.splice(i, 0, ...index, '');
	}

	const out = lines.join(nl);
	if (out !== text) {
		stale++;
		if (check) console.log(`${name}: field index is out of date`);
		else fs.writeFileSync(file, out);
	}
}

if (check && stale) {
	console.log(`::error::${stale} wiki table page(s) have an out-of-date field index. Run: node .github/scripts/wiki-field-index.js`);
	process.exit(1);
}
console.log(check ? 'field indexes are up to date' : `updated ${stale} page(s)`);
